"""Curated aesthetic associations, each grounded in two distinct sound descriptions."""
from dataclasses import dataclass


@dataclass(frozen=True)
class SoundCue:
    label: str
    name: str
    description: str
    reference: str


@dataclass(frozen=True)
class Aesthetic:
    id: str
    label: str
    name: str
    family: str
    interpretation: str
    interpretation_en: str
    reference: str
    contexts: tuple[str, ...]
    cues: tuple[SoundCue, SoundCue]
    branch: str
    kind: str = "scene"
    aliases: tuple[str, ...] = ()

    @property
    def description(self):
        return "; ".join(cue.description for cue in self.cues)


def group(family, rows):
    for key, label, name, reading, english, reference, contexts, first, second, *branch in rows:
        yield Aesthetic("cue-" + key, label, name, family, reading, english, reference,
                        tuple(contexts.split(";")), (SoundCue(*first), SoundCue(*second)),
                        branch[0] if branch else key)


